{
  "summary": "A vibrant Neo-Brutalist SaaS landing page utilizing a dominant #ffe17c yellow, deep charcoal #171e19, and sage #b7c6c2 accents. It features high-contrast black borders, hard offset shadows, and bold geometric typography to convey professional confidence with a playful edge.",
  "style": {
    "description": "The style is a modern take on Neo-Brutalism. Typography pairs the high-impact 'Cabinet Grotesk' (weights 400-800) for headings with 'Satoshi' for readability. The palette uses #ffe17c as a primary background, balanced by #171e19 charcoal and #b7c6c2 sage. Visual elements are defined by 2px solid black borders and 4px-8px hard shadows (no blur). Micro-interactions involve 'translate' effects on hover where buttons move 4px to 'fill' their shadow space.",
    "prompt": "Create a design based on Neo-Brutalist principles. Colors: Primary #ffe17c (Yellow), Background #171e19 (Charcoal), Accent #b7c6c2 (Sage), UI #ffffff (White), Text #000000 (Black). Typography: Headings in 'Cabinet Grotesk' (Extrabold, tracking-tighter), Body in 'Satoshi' (Medium, 500). UI Elements: Use 2px solid black borders on all cards, buttons, and sections. Implement 'Hard Shadows' using box-shadow: 4px 4px 0px 0px #000000 for standard elements and 8px 8px 0px 0px #000000 for large containers. Buttons should have a hover state that transforms: translate(4px, 4px) and removes the shadow to simulate a physical press. Include a 32px x 32px radial dot pattern (opacity 10%) on primary yellow backgrounds."
  },
  "layout_and_structure": {
    "description": "A vertically stacked landing page with high-contrast section transitions. It moves from a high-energy yellow hero to a dark charcoal social proof bar, followed by white/yellow feature grids and a dark-mode 'how it works' flow.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Fixed header at top-0, h-20, background #ffe17c, border-b-2 border-black. Left: Logo with a 10x10 black square icon containing a #ffe17c bolt. Center: Horizontal links in bold Satoshi. Right: 'Start Free Trial' button (Black background, white text, 2px border, hard shadow)."
      },
      {
        "part": "Hero Section",
        "prompt": "Two-column grid on #ffe17c background with radial dot pattern. Left column: Badge 'NEW: AI Content Assistant 2.0' (White, pill-shaped, 2px border). Heading: 'Cabinet Grotesk' 8xl, black, with one keyword using -webkit-text-stroke: 2px black and transparent fill. CTA group: Primary black button with 8px hard shadow, secondary white button with 4px hard shadow. Right column: Browser mockup (White, 2px border, 12px hard shadow) showing a dashboard with revenue charts and sage-colored accent panels."
      },
      {
        "part": "Social Proof Marquee",
        "prompt": "Full-width bar, background #171e19, border-b-2 border-black. Contains a continuous horizontal marquee of brand names (ACME, GLOBEX, etc.) in Cabinet Grotesk, color #b7c6c2, 50% opacity, moving infinitely at a slow linear pace."
      },
      {
        "part": "Problem vs Solution",
        "prompt": "White background section. Two large 3xl-rounded cards side-by-side. Card A (Problem): #f4f4f5, 2px dashed gray border, 70% opacity. Card B (Solution): #ffe17c, 2px solid black border, 8px hard shadow. Both cards use bold lists with custom check/x icons."
      },
      {
        "part": "Feature Grid",
        "prompt": "Background #ffe17c, border-y-2 border-black. 3-column grid of white cards. Each card: 2px border, 4px hard shadow. Top of card features a 16x16 icon box in #b7c6c2 that turns #ffe17c on hover. Headings are Cabinet Grotesk 2xl."
      },
      {
        "part": "How It Works",
        "prompt": "Dark mode section (Background #171e19). 3-step horizontal flow. Steps are marked by large 24x24 circles with 4px colored 'glow' borders (Sage, Yellow, White). Steps are connected by a dark gray #272727 horizontal line."
      },
      {
        "part": "Use Case Personas",
        "prompt": "White background. 3-column bento-style grid. Card 1: Sage (#b7c6c2). Card 2: Yellow (#ffe17c) with 8px hard shadow. Card 3: Dark Gray (#272727) with white text. Each card features a white 'pill' badge at the top indicating the user type."
      },
      {
        "part": "Testimonials",
        "prompt": "Background #b7c6c2. Grid of 3 white cards. Unique styling: Cards have asymmetric corner rounding (Top-Right and Bottom-Left are 3xl, Top-Left and Bottom-Right are 2px). Includes a 5-star rating in #ffbc2e yellow."
      },
      {
        "part": "Final CTA & Footer",
        "prompt": "Final CTA on #ffe17c with large centered heading. Footer in #171e19 with 4 columns. Social icons are 10x10 squares (#272727) with light gray borders that turn Yellow/Black on hover."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Neo-Brutalist Push Button",
      "description": "A high-contrast button that visually 'depresses' when hovered or clicked.",
      "prompt": "Implementation: background-color: #000; color: #fff; padding: 1rem 2rem; border: 2px solid #000; border-radius: 0.75rem; box-shadow: 8px 8px 0px 0px #000; transition: all 0.2s cubic-bezier(0.175, 0.885, 0.32, 1.275); On Hover: transform: translate(4px, 4px); box-shadow: 4px 4px 0px 0px #000;"
    },
    {
      "component": "Browser Mockup Dashboard",
      "description": "A stylized application UI container for marketing visuals.",
      "prompt": "Implementation: Background white, border 2px solid black, border-radius 1rem, shadow 12px 12px 0px black. Header bar: background black, contains three small colored circles (Red #ff5f57, Yellow #febc2e, Green #28c840). Content area uses a grid layout with sage #b7c6c2 and charcoal #171e19 internal cards."
    }
  ],
  "special_notes": "MUST: Maintain a strict 2px border-width on all interactive elements. MUST: Use only hex values #ffe17c, #171e19, and #b7c6c2 for branded sections. MUST: Ensure all shadows have 0 blur radius. DO NOT: Use gradients or soft shadows. DO NOT: Use rounded corners on buttons larger than 12px; keep the aesthetic geometric."
}

{
  "summary": "A sophisticated, typography-first design system using heavy geometric sans-serifs, offset text layering (echoes), and a clean, high-contrast monochromatic color palette to create an editorial, luxury-brutalist aesthetic.",
  "style": {
    "description": "The style is defined by its Swiss minimalist roots: heavy use of 'Clash Display' for bold, oversized headlines and 'Satoshi' for clean, functional body text. Colors are strictly neutral (#f2f2f2 background, #111111 text) with a gradient of grays (#bfbfbf to #d9d9d9) used for depth-creating background layers. The aesthetic is devoid of traditional icons or illustrative fluff, relying instead on geometric shapes, sharp borders, and high-impact font pairing.",
    "prompt": "Create a high-contrast minimalist UI using a Swiss-style aesthetic. \n- **Palette**: Backgrounds in off-white (#f2f2f2), primary text in deep black (#111111), and secondary elements in muted grays (#b6b5b5, #838282).\n- **Typography**: Headlines in 'Clash Display' (bold, weight 700), tracking -0.05em, leading 0.9. Body text in 'Satoshi' (medium, weight 500). \n- **The Echo Effect**: Primary hero text should be layered with 4-5 background repetitions. Each background layer is offset by -0.04em, -0.08em, -0.12em, and -0.16em respectively, with colors fading from #bfbfbf to #d9d9d9.\n- **Micro-interactions**: Use 700ms cubic-bezier(0.77, 0, 0.175, 1) for image reveals (clip-path: inset). Interactive elements should utilize grayscale-to-color transitions and subtle scale transforms (1.05x)."
  },
  "layout_and_structure": {
    "description": "The structure follows a clean vertical flow with significant whitespace and an asymmetrical grid for showcase sections. It moves from a high-impact typographic hero to a structured three-column informational grid, followed by a dynamic masonry-style image layout.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Sticky header with a height of 80px. Background: #f2f2f2 with 90% opacity and backdrop-blur(12px). Links: 14px uppercase Satoshi with 120ms color transition to #b6b5b5. Include a pill-shaped contact button with a 1px solid #1e1e1e border that inverts on hover."
      },
      {
        "part": "Hero Section",
        "prompt": "Full-width section with a height of 70vh to 100vh. Center-align a massive text element (11vw or 180px). Implement the 'Echo Stack' with at least 4 layers of background text in varying light gray tones. Ensure the main foreground text is #111111. No imagery, just pure typographic weight."
      },
      {
        "part": "Philosophy / Narrative Section",
        "prompt": "Centered block with a vertical hairline divider (1px #1e1e1e/10) leading into the section. Large-scale quote (4xl to 6xl) using Clash Display, featuring a single keyword in a contrasting serif italic font for editorial flair. Beneath, a 3-column grid with 32px gaps, each column featuring a bold H3 and light-weight Satoshi body text."
      },
      {
        "part": "Asymmetrical Showcase Grid",
        "prompt": "A 12-column grid featuring mixed aspect ratios. Section include: 1. A large 8-column rectangular card with rounded-sm corners. 2. A vertical 4-column pill-shaped card (full border-radius). 3. A circular 5-column aspect-square image. 4. A wide 7-column rectangle. All images should start with a 20% grayscale filter, transitioning to 100% color and 1.05x scale on hover."
      },
      {
        "part": "Bespoke Service Cards",
        "prompt": "3-column grid of cards with #1e1e1e/10 borders. Backgrounds transition from transparent to #ffffff on hover. Each card contains a small geometric icon container (64x64px) that rotates 12 degrees on hover. Use arrow-right icons for CTAs with a tracking-wide bold Satoshi font."
      },
      {
        "part": "Footer",
        "prompt": "Deep dark theme (#1e1e1e) with 60% opacity off-white text (#f6f6f6). 4-column layout including brand summary, navigation, company links, and contact details with Lucide-style line icons. Include a thin 5% opacity white top border."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Typographic Echo Stack",
      "description": "A rhythmic text layering technique using CSS absolute positioning.",
      "prompt": "Layer 5 instances of the same word. The top layer is #111111. Layers 2-5 are positioned absolutely beneath it, each shifted left and up by increments of 0.04em. Background colors: #bfbfbf, #c9c9c9, #d1d1d1, #d9d9d9. Set pointer-events: none for all background layers."
    },
    {
      "component": "Pill-Shaped Vertical Showcase",
      "description": "A high-aspect ratio container with full border radius for editorial imagery.",
      "prompt": "Container with height: 500px and border-radius: 9999px. Overflow: hidden. Inside, place an image that scales on hover. Center a circular overlay that only becomes visible (opacity 1) when the parent is hovered, containing secondary text in a thin border."
    }
  ]
}

{
  "summary": "Design a 'Softly' themed mobile-first landing page for a digital wellness app using a warm, desaturated pastel palette, high-end grain textures, and fluid, low-velocity animations. The UI should feel like a 'digital living room'—minimalist, tactile, and intentionally slow.",
  "style": {
    "description": "The style essence combines 'Digital Minimalism' with 'Gen-Z Lifestyle' aesthetics. Typography pairs the clean, rounded 'Outfit' sans-serif with the whimsical 'Reenie Beanie' cursive. The color story uses #292524 for soft-black text against a primary background of #FDFCF8. Visual depth is achieved through high-radius blurs on background blobs and a persistent 35% opacity SVG noise/grain overlay for a paper-like feel.",
    "prompt": "Create a visual style based on 'Digital Wellness'. \n- **Color Palette**: Background: #FDFCF8; Sage: #E8EFE8; Lavender: #EFEDF4; Peach/Coral: #FFB7B2 (Primary Accent); Dark Text: #292524; Muted Text: #78716C.\n- **Typography**: Primary font: 'Outfit' (Sans-serif), Headings at 48px-96px with tracking-tight (-0.025em), Sentence-case only. Accent font: 'Reenie Beanie' (Cursive) for expressive emphasis.\n- **Visual Effects**: 0.35 opacity fractal noise grain overlay. Border-radius: 2rem to 4rem for all containers. Soft shadows: 0 4px 20px -2px rgba(0,0,0,0.05).\n- **Animations**: Use 'reveal-on-scroll' (translateY: 30px to 0, opacity 0 to 1, duration 0.8s). Floating animations for background blobs (6s loop, translateY +/- 10px)."
  },
  "layout_and_structure": {
    "description": "A vertical, single-column flow designed for mobile-first consumption. It transitions from a spacious hero to interactive horizontal scrolls, ending in high-contrast (dark on light) conversion sections.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Floating pill-shaped nav bar: 70% white opacity, 20px backdrop-blur. Contains a small circular logo (Coral #FFB7B2 with white dot), text links in 14px Outfit Medium, and a dark stone (#292524) pill CTA button. Width should be constrained to 100% minus 32px on mobile."
      },
      {
        "part": "Hero Section",
        "prompt": "Center-aligned layout. Two large blurred background blobs (#FFE4E1 and #E6E6FA) at 60% opacity. Headline uses 72px Outfit with a handwritten cursive word inserted for emphasis. Sub-headline max-width 500px. Dual CTA buttons: primary pill in Coral #FFB7B2 with soft shadow, secondary pill in white with 1px stone-200 border."
      },
      {
        "part": "Horizontal Scenario Scroll",
        "prompt": "A list of cards that scroll horizontally. Each card: 288px width, 160px height, white background, rounded-3xl (24px). Top-left timestamp in 14px stone-400, bottom text in 20px stone-800. On hover, the text color should change to a pastel accent."
      },
      {
        "part": "App Experience Preview",
        "prompt": "A three-mockup stacked layout. Center phone is 300x620px, fully opaque, with a Coral (#FFB7B2) pulsing 'Breathe' button. Left and right phones are 280x580px, 80% opacity, slightly translated vertically (left +48px, right +96px) to create a cascading effect. Use Sage (#E8EFE8) and Lavender (#EFEDF4) for screen backgrounds."
      },
      {
        "part": "Diary Entry Testimonials",
        "prompt": "Two-column grid for desktop, single for mobile. Cards should have a slight rotation (+1 or -1 degree) to mimic physical notes. Background: White. Signature style: A 32px horizontal line followed by 'Reenie Beanie' cursive text in 24px stone-500."
      },
      {
        "part": "Waitlist Conversion",
        "prompt": "Full-width section with a central focus. Background uses high-blur floating gradients. Feature a dark stone #292524 rounded-square icon at the top with a coral dot. Form: Email input (rounded-full, bg-stone-50) and a black submit button that scales up on hover."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Interactive FAQ Accordion",
      "description": "Smooth expanding/collapsing questions with icon rotation.",
      "prompt": "Container: white background, 16px rounded corners, 1px stone-100 border. Header: 24px padding, 500 weight text, 'plus' icon that rotates 45 degrees. Content: Transition from height 0 to auto using duration-500ms ease-in-out. Reveal text with bottom padding 24px."
    },
    {
      "component": "Grain Overlay",
      "description": "A global texture layer that makes the flat design feel analog.",
      "prompt": "A fixed div covering the viewport with z-index 50. Background-image uses an SVG filter with feTurbulence (baseFrequency 0.65). Mix-blend-mode: overlay. Opacity: 0.35. Pointer-events: none."
    }
  ]
}

{
  "summary": "A futuristic 'Obsidian & Lime' glassmorphism design system characterized by high contrast, blurred transparency, and tech-industrial typography. It utilizes a bento-grid structure and floating layouts to create a multi-layered, interactive experience.",
  "style": {
    "description": "The style is defined by its 'dark-mode-first' approach using an obsidian base (#0a0a0a) and high-vibrancy lime accents (#ccff00). Typography pairings involve 'Space Grotesk' for high-impact, tight-tracked headings and 'JetBrains Mono' for technical metadata. Glassmorphism is executed with subtle white overlays (3% opacity) combined with intense 16px background blurs. Visual depth is added through grainy noise textures and 60px grid backgrounds.",
    "prompt": "Base theme: Deep black (#000000) shell with obsidian surfaces (#0c0c0c). Primary accent color: Neon Lime (#ccff00). Secondary accent: Emerald Glow (#10b981). Typography: Headings in 'Space Grotesk' (weights: 300 to 700, tracking: -0.06em), body in 'Space Grotesk' (weight: 400), and technical labels in 'JetBrains Mono' (uppercase, tracked out). Glassmorphism specs: Background: rgba(255, 255, 255, 0.03), Backdrop-filter: blur(16px), Border: 1px solid rgba(255, 255, 255, 0.1). Text colors: Primary White (#ebebeb), Secondary White (opacity 60%), Disabled/Muted (opacity 30%). Decorative elements: 60x60px linear-gradient grid pattern, 15% opacity noise SVG overlay, and large 'glow-sphere' radial gradients with 120px blur filters. Animation curves: ease-in-out for floating elements, cubic-bezier(0.4, 0, 0.2, 1) for transitions."
  },
  "layout_and_structure": {
    "description": "A 'floating shell' architecture where the entire site content resides in a rounded container (2.5rem radius) nested within a black viewport. The internal layout follows a bento-grid methodology for features and a high-contrast split-section for the hero.",
    "prompts": [
      {
        "part": "Floating Shell Container",
        "prompt": "Wrap the entire site in a container with max-width 1600px. Apply 'rounded-[2.5rem]', 'ring-1 ring-white/10', and 'shadow-2xl'. This shell should have a background of #0c0c0c."
      },
      {
        "part": "Navigation",
        "prompt": "Fixed/Absolute header. Logo on the left (rounded-xl lime box with black initial). Center: Pill-shaped navigation bar (rgba(255,255,255,0.05) background, backdrop-blur, rounded-full) containing links with white/70 opacity. Right side: Monospaced system status indicator with a pulsing lime dot next to a white rounded-full button."
      },
      {
        "part": "Hero Section",
        "prompt": "Split 12-column grid. Left (7 cols): Giant typography (font-size: 7.5rem, line-height: 0.85) featuring an italicized gradient span (#ccff00 to white). Include a mono-styled 'AI label' above the heading. Right (5 cols): Interactive glassmorphism mockup shell with floating cards (float-anim: 6s infinite ease-in-out) and an 'AI Cursor' floating label (#ccff00 background)."
      },
      {
        "part": "Bento Grid Features",
        "prompt": "Grid-cols-4 for desktop. Cards should have 'rounded-[2.5rem]' and 'border border-white/10'. Large card: spans 2x2, features internal data visualization (vertical bars). Tall card: spans 1x2, features color/token swatches. Accent card: solid #ccff00 background with black text and noise texture. Hover state: border color changes to #ccff00/40."
      },
      {
        "part": "Contrast Section (Methodology)",
        "prompt": "Full-width section with light-grey background (#e5e5e5) and dark text (#000000). Rounded top corners (4rem radius). Features a numbered list (01, 02, 03) in monospaced font inside circles. Right side: Greyscale circular portrait with a glassmorphism testimonial card overlaying the bottom."
      },
      {
        "part": "Footer",
        "prompt": "Obsidian background (#000000). Top: Massive background watermark text 'SUPER' (10rem size, 5% opacity). Call to action: Oversized lime button (#ccff00) with a slide-up white background transition on hover. Bottom: 3-column footer with policy links, social icons (hollow circles), and monospaced copyright info."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Glass Floating Card",
      "description": "A multi-layered glass element that appears to float over the background.",
      "prompt": "Create a div with `background: rgba(255, 255, 255, 0.03)`, `backdrop-filter: blur(16px)`, `border: 1px solid rgba(255, 255, 255, 0.1)`, and `border-radius: 1.5rem`. Add a `float-anim` using `@keyframes float { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(-10px); } }`."
    },
    {
      "component": "Neon Pulse Button",
      "description": "High-visibility primary action button with a glowing shadow.",
      "prompt": "Button style: `background-color: #ccff00`, `color: #000000`, `font-weight: 700`, `border-radius: 9999px`, `padding: 1rem 2rem`. Shadow: `box-shadow: 0 0 30px rgba(204, 255, 0, 0.3)`. Hover: `scale: 1.05`."
    },
    {
      "component": "System Status Tag",
      "description": "Monospaced utility tag for technical labels.",
      "prompt": "Container: `display: flex`, `align-items: center`, `gap: 0.5rem`, `font-family: 'JetBrains Mono'`, `text-transform: uppercase`, `letter-spacing: 0.2em`, `font-size: 10px`. Dot: `width: 6px`, `height: 6px`, `border-radius: 50%`, `background-color: #ccff00`, `animation: pulse 2s infinite`."
    }
  ],
  "special_notes": "MUST use #ccff00 as the primary accent. MUST NOT use standard system fonts; stick to Space Grotesk and JetBrains Mono. MUST maintain at least 16px blur on all glass elements to ensure legibility. MUST use grid patterns and noise overlays to prevent 'flat' dark mode looks. Ensure all container corners have a high radius (at least 2rem) for a modern, hardware-like feel."
}

{
  "summary": "The 'Kinetic Orange' style is a digital-first brutalist aesthetic that uses heavy typography and motion to create a sense of urgency and technical sophistication. It relies on a three-color system (Orange, Black, White) and sharp geometric layouts.",
  "style": {
    "description": "High-impact brutalist theme. It pairs the heavy weight of 'Archivo Black' for display text with the technical precision of 'Space Mono' for metadata and labels. The primary color is a vibrant electric orange (#FF4D00). Visuals are defined by thick borders (2px+), skewed sections, and continuous marquee animations.",
    "prompt": "Create a design with a primary background color of #FF4D00 and deep black #000000 text. \n- **Typography**: Headers in 'Archivo Black', uppercase, tracking -0.04em, line-height 0.85-0.9. Metadata and UI labels in 'Space Mono', tracking -0.02em. Body text in 'Inter'. \n- **Color Palette**: Brand Orange (#FF4D00), Solid Black (#000000), and Pure White (#FFFFFF) for high-contrast accents on black backgrounds. \n- **Borders**: 2px solid #000000 for section dividers and buttons. \n- **Motion**: Use linear marquees for text-heavy sections. Implement a 'spin' animation for circular indicators (12s duration). \n- **Interactions**: Hover states should include horizontal translations (translate-x-4) and scale transforms (scale-110). Selection color should be background: black; color: #FF4D00;"
  },
  "layout_and_structure": {
    "description": "A vertically stacked layout with full-width sections. It uses a floating 'pill' navigation bar and incorporates skewed transitions between sections to break the grid.",
    "prompts": [
      {
        "part": "Floating Navigation",
        "prompt": "A fixed top navigation with a logo on the left and social icons on the right. In the center, a floating black 'pill' container (background #000000, rounded-full) housing links in white 'Space Mono' (size 12px). Links should transition to black text on white background on hover."
      },
      {
        "part": "Typographic Hero Section",
        "prompt": "A fullscreen header with the main headline centered in 'Archivo Black' at 16vw size. Below the headline, a 2px black horizontal border separates the hero from a metadata row containing a 'Based in...' label (left), a rotating circular 'Scroll Down' text indicator (center), and a multi-line title/role (right)."
      },
      {
        "part": "Skewed Marquee Section",
        "prompt": "A full-width section with background #000000, skewed at -2deg. Contains two rows of infinite scrolling text. Row 1: Orange text (#FF4D00) in Archivo Black, 10vw size. Row 2: White text with 80% opacity, scrolling in reverse."
      },
      {
        "part": "Vertical Service List",
        "prompt": "A dark section (background #000000, text #FFFFFF). Items are separated by 1px white/20% borders. Each item features a leading number in #FF4D00 (Space Mono), a large uppercase title (Archivo Black, 7vw), and a row of pill-shaped tags. On hover, the title moves right and a large #FF4D00 arrow icon reveals at 45 degrees."
      },
      {
        "part": "Giant CTA and Footer",
        "prompt": "A centered CTA with 14vw heading. A large rounded-full button (#000000 background, white text) that scales up on hover. Footer is separated by a 2px black top border, containing copyright info and horizontal social links in Space Mono (12px)."
      }
    ]
  },
  "special_ui_components": [
    {
      "component": "Rotating Scroll Indicator",
      "description": "A circular SVG path with text that rotates infinitely.",
      "prompt": "Create a 144px diameter circle. Inside, use an SVG <textPath> on a circular path to repeat the string 'Scroll Down • ' 3-4 times. Use font 'Space Mono', size 9px, weight bold, uppercase. Place a static arrow-down icon (Lucide) in the center. Animate the SVG text container with a linear rotation (360deg over 12s)."
    },
    {
      "component": "Brutalist Service Card",
      "description": "Interactive list item with reveal effects.",
      "prompt": "A list item spanning 100% width with a top border. Layout: [Index (Orange, Mono)] [Title + Tags (White, Archivo)] [Arrow Icon (Hidden, Orange)]. On hover: Background shifts to white/5% opacity, Title translates +16px horizontally, Arrow opacity becomes 1 and rotates 45deg."
    }
  ],
  "special_notes": "MUST: Maintain extremely high contrast. MUST: Use only uppercase for Archivo Black headers. MUST: Ensure all borders are sharp (no rounded corners except for pill-shaped buttons and navigation). DO NOT: Use gradients, drop shadows (except for navigation depth), or soft pastels. DO NOT: Use standard sans-serifs for headlines."
}

{
  "summary": "Raw Form is a high-contrast, brutalist design system that prioritizes typographic drama and atmospheric depth. It replaces traditional container-heavy UI with massive type breaks, soft organic gradients, and a sharp, grid-based hierarchy.",
  "style": {
    "description": "The style blends the raw energy of Swiss Brutalism with a refined, warm color palette. It uses 'Clash Display' for heavy headlines and 'Satoshi' for functional sans-serif body text. The color scheme is anchored by #E4E2DD (Base), #1E1E1E (Primary), and #DB4A2B (Accent Red). Animations are smooth, utilizing cubic-bezier curves for a premium feel.",
    "prompt": "Apply a Brutalist Poster aesthetic. Background: #E4E2DD; Primary Text: #1E1E1E. Typography: Use 'Clash Display' for headings (700 weight, tight tracking -0.05em, leading 0.75) and 'Satoshi' for body (400-500 weight). Accent Colors: #DB4A2B (Red-Orange), #F8A348 (Warm Orange), #FF89A9 (Soft Pink). Gradients: Use large, soft-blurred radial blobs (100px+ blur) with `mix-blend-mode: multiply` behind typography. Global Animations: Implement a slide-up entrance for all elements using `cubic-bezier(0.16, 1, 0.3, 1)` over 0.8s. Selection Color: #DB4A2B with white text. Scrollbar: 8px width, #DB4A2B thumb, #E4E2DD track."
  },
  "layout_and_structure": {
    "description": "A vertically-oriented layout featuring full-viewport typographic heroes, massive category dividers, and borderless product grids.",
    "prompts": [
      {
        "part": "Navigation",
        "prompt": "Minimalist fixed navigation. Left: Brand logo in 'Clash Display' (bold, uppercase, 2xl). Center: Text links in Satoshi (medium, 14px, tracked out 0.1em). Right: Icon set (Search, Bag) using 20px Lucide icons. Apply `mix-blend-difference` on mobile; standard dark text on desktop."
      },
      {
        "part": "Hero Section",
